package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaMlDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_ma_amiltu" to DuaText("എൻറെ തിന്മകളിൽ നിന്നുള്ള അഭയം", "അല്ലാഹുവേ, ഞാൻ ചെയ്തതിൻ്റെ തിന്മയിൽ നിന്നും ഞാൻ ചെയ്യാത്തതിൻ്റെ തിന്മയിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "ആയിഷ (റ) യുടെ അഭിപ്രായത്തിൽ പ്രവാചകൻറെ ഒരു ദുആ.", "ചെയ്തതിൻ്റെയും ചെയ്തതിൻ്റെയും അനന്തരഫലങ്ങളിൽ നിന്നുള്ള സംരക്ഷണം."),
        "dua_jahdil_bala" to DuaText("കഠിനമായ പരീക്ഷണങ്ങളിൽ നിന്നുള്ള അഭയം", "അല്ലാഹുവേ, കഠിനമായ വിചാരണയിൽ നിന്നും ദുരിതത്തിൽ നിന്നും തിന്മായ കൽപനയിൽ നിന്നും ശത്രുക്കളുടെ മഹത്വത്തിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "കഠിനമായ പരീക്ഷണങ്ങളിൽ നിന്നും ശത്രുക്കളുടെ ഉല്ലാസത്തിൽ നിന്നും അഭയം തേടുക.", "നബി (സ) ഈ നാല് കാര്യങ്ങളിൽ നിന്ന് അഭയം തേടി."),
        "dua_fitnat_ghina_faqr" to DuaText("സമ്പത്തിന്റെയും ദാരിദ്ര്യത്തിന്റെയും പരീക്ഷണങ്ങളിൽ നിന്നുള്ള അഭയം", "അല്ലാഹുവേ, അലസതയിൽ നിന്നും വാർദ്ധക്യത്തിൽ നിന്നും പാപത്തിൽ നിന്നും കടത്തിൽ നിന്നും ശവകുടീരത്തിൻറെ വിചാരണയിലും ശിക്ഷയിലും നിന്നും നരകത്തിൻറെ വിചാരണയിലും ശിക്ഷയിലും നിന്നും സമ്പത്തിൻറെ ദോഷത്തിൽ നിന്നും ദാരിദ്ര്യത്തിൻറെ വിചാരണയിലും നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "ശവകുടീരം, നരകം, സമ്പത്ത്, ദാരിദ്ര്യം (ദുആയുടെ ഭാഗം) എന്നിവയുടെ പരീക്ഷണങ്ങളിൽ നിന്ന് അഭയം തേടുക.", "നബി (സ) യിൽ നിന്നുള്ള സമഗ്രമായ അഭയം."),
        "dua_kufr_faqr" to DuaText("അവിശ്വാസത്തിൽ നിന്നും ദാരിദ്ര്യത്തിൽ നിന്നുമുള്ള അഭയം", "അല്ലാഹുവേ, ഞാൻ അവിശ്വാസത്തിൽ നിന്നും ദാരിദ്ര്യത്തിൽ നിന്നും നിന്നിൽ അഭയം തേടുന്നു. ശവകുടീരശിക്ഷയിൽ നിന്നും നിന്നിൽ അഭയം തേടുന്നു. നിന്നല്ലാതെ ദൈവമില്ല.", "രാവിലെയും വൈകുന്നേരവും മൂന്ന് തവണ.", "നബി (സ) ഇത് പറയുന്നത് അബൂബക്കർ (റ) കേട്ടു."),
        "dua_sharri_sami" to DuaText("എൻ്റെ ഇന്ദ്രിയങ്ങളുടെ തിന്മയിൽനിന്ന് അഭയം തേടുക", "അല്ലാഹുവേ, എൻ്റെ കേൾവിശക്തിയുടെ തിന്മയിൽനിന്നും എൻ്റെ കാഴ്ചശക്തിയുടെ തിന്മയിൽനിന്നും എൻ്റെ നാവിൻ്റെ തിന്മയിൽനിന്നും എൻ്റെ ഹൃദയത്തിൻ്റെ തിന്മയിൽനിന്നും എൻ്റെ ആഗ്രഹത്തിൻ്റെ തിന്മയിൽനിന്നും ഞാൻ അങ്ങയിൽ അഭയം തേടുന്നു.", "ഷക്കൽ ഇബ്നു ഹുമയ്ദിന് (റ) പഠിപ്പിച്ചു.", "കൈകാലുകളെയും സ്വയം പാപത്തിൽ നിന്ന് സംരക്ഷിക്കുന്നതിനുള്ള ഒരു ദുആ."),
        "dua_hadm_gharaq" to DuaText("പെട്ടെന്നുള്ള മരണങ്ങളിൽ നിന്നും അപകടങ്ങളിൽ നിന്നുമുള്ള അഭയം", "അല്ലാഹുവേ, (കെട്ടിടത്തിൻ്റെ) തകർച്ചയിൽ നിന്നും, ഉയരത്തിൽ നിന്ന് വീഴുന്നതിൽ നിന്നും, മുങ്ങിമരണത്തിൽ നിന്നും, കത്തിൽ നിന്നും വാർദ്ധക്യത്തിൽ നിന്നും, മരണസമയത്ത് എന്നെ വഴിതെറ്റിക്കുന്ന ഷൈതാനിൽ നിന്നും, നിൻറെ പാതയിൽ നിന്ന് ഓടിപ്പോകുമ്പോൾ മരിക്കുന്നതിൽ നിന്നും, (വിഷമുള്ള) കുത്ത് മൂലം മരിക്കുന്നതിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "അപകടങ്ങളിൽ നിന്നും മോശം മരണത്തിൽ നിന്നും അഭയം തേടുക.", "നബി (സ) യുടെ ഒരു അഭയം."),
        "dua_ju_khiyanah" to DuaText("പട്ടിണിയിൽ നിന്നും വഞ്ചനയിൽ നിന്നുമുള്ള അഭയം", "അല്ലാഹുവേ, ഞാൻ വിശപ്പിൽനിന്ന് നിന്നിൽ അഭയം തേടുന്നു. കാരണം അത് ഒരു ദുഷ്ട കൂട്ടാളി ആണ്. വഞ്ചനയിൽനിന്ന് ഞാൻ നിന്നിൽ അഭയം തേടുന്നു. കാരണം അത് ഒരു ദുഷ്ടവിശ്വാസിയാണ്.", "പട്ടിണിയിൽ നിന്നും വഞ്ചനയിൽ നിന്നും അഭയം തേടുക.", "നബി (സ) യുടെ ഒരു അഭയം."),
        "dua_huda_tuqa" to DuaText("മാർഗനിർദേശം, ഭക്തി, പവിത്രത, പര്യാപ്തത", "അല്ലാഹുവേ, മാർഗദർശനവും ഭക്തിയും പവിത്രതയും സ്വയംപര്യാപ്തതയും ഞാൻ നിന്നോടു യാചിക്കുന്നു.", "നബി (സ) യുടെ ഹ്രസ്വവും സമഗ്രവുമായ ഒരു ദുആ.", "മതത്തിൻ്റെയും ഈ ലോകത്തിൻ്റെയും നാല് അടിസ്ഥാനപരമായ അനുഗ്രഹങ്ങൾ."),
        "dua_aslih_li_dini" to DuaText("എൻ്റെ മതത്തെയും ലോകത്തെയും പരലോകത്തെയും തിരുത്തുക.", "അല്ലാഹുവേ, എൻറെ എല്ലാ കാര്യങ്ങളുടെയും സംരക്ഷണമായ എൻറെ മതം നീക്കുക. എൻറെ ഐഹികജീവിതം നീക്കുക. അതിൽ എൻറെ ഉപജീവനമാർഗ്ഗവും. എൻറെ പരലോകത്തെ ഞാൻ തിരിച്ചുകൊണ്ടുപോകും. എനിക്ക് എല്ലാ നന്മകളിലും ജീവിതം വർദ്ധിപ്പിക്കുക. മരണത്തെ എനിക്ക് എല്ലാ തിന്മകളിൽ നിന്നും ആശ്വാസം നൽകുക.", "മതത്തെ, ഈ ലോകത്തെയും, പരലോകത്തെയും-ഈ മൂന്നും പരിഷ്കരിക്കുക.", "നബി (സ) യുടെ സമഗ്രമായ ഒരു ദുആ."),
        "dua_musarrifal_qulub" to DuaText("ഞങ്ങളുടെ ഹൃദയങ്ങളെ അങ്ങയുടെ അനുസരണത്തിലേക്ക് തിരിക്കുക.", "അല്ലാഹുവേ, ഹൃദയങ്ങൾ തിരിക്കുന്നവരേ, അങ്ങയുടെ അനുസരണത്തിലേക്ക് ഞങ്ങളുടെ ഹൃദയങ്ങൾ തിരിക്കുക.", "അനുസൃതതയിൽ ഹൃദയം ഉറച്ചുനിർത്താനുള്ള ഒരു ദുആ.", "എല്ലാ മനുഷ്യരുടെയും ഹൃദയങ്ങൾ പരമകാരുണികൻറെ രണ്ട് വിരലുകൾക്കിടയിലാണ്."),
        "dua_jannah_nar" to DuaText("ജന്നയെ, തീയിൽ നിന്നുള്ള അഭയം, ചോദിക്കുന്നു", "അല്ലാഹുവേ, ഞാൻ നിന്നോടു സ്വർഗ്ഗം യാചിക്കുകയും നരകത്തിൽനിന്ന് നിന്നിൽ അഭയം തേടുകയും ചെയ്യുന്നു.", "താഷാഹ്ഹുദിന് ശേഷമോ അല്ലെങ്കിൽ എപ്പോൾ വേണമെങ്കിലും.", "നബി (സ) പറഞ്ഞുഃ നമ്മുടെ ദുആകളും ഇതിനെ ചുറ്റിപ്പറ്റിയാണ്."),
        "dua_khayri_kullih" to DuaText("എല്ലാം നന്നായിരിക്കുന്നു, ഇപ്പോളും പിന്നീട്", "അല്ലാഹുവേ, ഞാൻ നിന്നോടു എല്ലാ നന്മയും-ഉടനടി വരുന്നതും വൈകുന്നതും, എനിക്കറിയാവുന്നതും അറിയാത്തതും-ഞാൻ നിന്നോട് അഭ്യർത്ഥിക്കുന്നു. ഉടനടി വരുന്നതും വൈകുന്നതും, എനിക്കറിയാവുന്നതും അറിയാത്തതും-എല്ലാ തിന്മകളിൽ നിന്നും ഞാൻ നിന്നോട് അഭയം തേടുന്നു. അല്ലാഹുവേ, ഞാൻ നിന്നോടുതന്നെ സ്വർഗ്ഗം തേടുന്നു. എന്തൊക്കെ വാക്കുകളും പ്രവർത്തനങ്ങളും എന്നെ അതിന് അടുത്തുകൊണ്ടുവന്നാലും. നരകത്തിൽ നിന്നും, എന്തൊക്കെ വാക്കുകളും പ്രവൃത്തികളും എന്നെ അതിന് അടുത്തുകൊണ്ടുവന്നാലും ഞാൻ നിന്നോട് അഭയം തേടുന്നു.", "നബി (സ) ആയിഷയെ (അല്ലാഹുവിൻറെ ഭാഗം) ഈ സമഗ്രമായ ദുആ പഠിപ്പിച്ചു.", "എല്ലാ നന്മയും ശേഖരിക്കുന്ന ഒരു ദുആ."),
        "dua_ihdini_saddidni" to DuaText("എന്നെ നയിക്കുകയും എന്നെ കൃത്യതയോടെ നിലനിർത്തുകയും ചെയ്യുക", "അല്ലാഹുവേ, എന്നെ നേർവഴിയിലാക്കുകയും ശരിയായ പാതയിൽ നയിക്കുകയും ചെയ്യേണമേ.", "നബി (സ) അത് അലി (റ) യെ പഠിപ്പിച്ചു.", "മാർഗനിർദേശത്തെ ഒരു റോഡിലൂടെ നയിക്കുന്നതായും സാദാദിനെ അമ്പിന്റെ നേർത്തതായും കരുതുക."),
        "dua_hubbaka" to DuaText("അല്ലാഹുവിൻ്റെ സ്നേഹം ചോദിക്കുക.", "അല്ലാഹുവേ, നിൻറെ സ്നേഹവും നിന്നെ സ്നേഹിക്കുന്നവരുടെ സ്നേഹവും എന്നെ നിൻറെ സ്നേഹത്തിലേക്ക് കൊണ്ടുവരുന്ന പ്രവർത്തനങ്ങളും ഞാൻ നിന്നോടു ചോദിക്കുന്നു. അല്ലാഹുവേ, എന്നേക്കാളും എൻറെ കുടുംബത്തേക്കാളും തണുത്ത വെള്ളത്തേക്കാളും നിൻറെ സ്നേഹത്തെ എനിക്ക് പ്രിയങ്കരമാക്കുക.", "നബി (സ) നൽകിയ ദാവൂദ് (അ. സ.) ൻറെ ദുആ.", "അല്ലാഹുവിൻറെ സ്നേഹമാണ് ഏറ്റവും വലിയ സമ്പത്ത്."),
        "dua_filal_khayrat" to DuaText("നന്മ ചെയ്യുകയും തിന്മ ഉപേക്ഷിക്കുകയും ചെയ്യുക", "അല്ലാഹുവേ, സൽകർമ്മങ്ങൾ ചെയ്യാനും തിന്മ ഉപേക്ഷിക്കാനും ദരിദ്രരെ സ്നേഹിക്കാനും എന്നെ പ്രാപ്തനാക്കാനും നീ എന്നോട് ക്ഷമിക്കാനും എന്നോട് കരുണ കാണിക്കാനും ഞാൻ നിന്നോടു അപേക്ഷിക്കുന്നു. ഒരു ജനതയ്ക്ക് വേണ്ടി ഒരു വിചാരണ നടത്താൻ നീ ഉദ്ദേശിക്കുമ്പോൾ എന്നെ പരീക്ഷിക്കപ്പെടാതെ കൊണ്ടുപോവുകയും ചെയ്യുക. നിൻറെ സ്നേഹവും നിന്നെ സ്നേഹിക്കുന്നവരുടെ സ്നേഹവും എന്നെ നിൻറെ സ്നേഹത്തോട് അടുക്കുന്ന പ്രവൃത്തികളോടുള്ള സ്നേഹവും ഞാൻ നിന്നോടു ചോദിക്കുന്നു.", "അല്ലാഹു ഈ ദുആ നബി (സ) യെ സ്വപ്നത്തിൽ പഠിപ്പിച്ചു.", "നബി (സ) പറഞ്ഞുഃ ഇത് സത്യമാണ്, അതിനാൽ അത് പഠിക്കുകയും പഠിപ്പിക്കുകയും ചെയ്യുക."),
        "dua_bi_ilmikal_ghayb" to DuaText("ജീവിതം നല്ലതായിരിക്കുമ്പോൾ എന്നെ ജീവിക്കാൻ അനുവദിക്കുക.", "അല്ലാഹുവേ, അദൃശ്യത്തെക്കുറിച്ചുള്ള നിൻറെ അറിവിലൂടെയും സൃഷ്ടിയുടെ മേൽ നിൻറെ ശക്തിയിലൂടെയും എന്നെ ജീവിച്ചിരിക്കേണമേ. എനിക്ക് ജീവിതം നല്ലതാണെന്ന് നീ അറിയുന്ന കാലത്തോളം എന്നെ ജീവിച്ചിരിക്കേണമേ. മരണം എനിക്ക് നല്ലതാണെന്ന് നീ അറിയുമ്പോൾ എന്നെ കൊണ്ടുപോകണമേ. അല്ലാഹുവേ, ഞാൻ നിന്നോടു സ്വകാര്യമായും പരസ്യമായും നിന്നെ ഭയപ്പെടുവാനും, സംതൃപ്തിയിലും കോപത്തിലും സത്യവാക്ക് പറയുവാനും, ദാരിദ്ര്യത്തിലും സമ്പത്തിലുമുള്ള മിതത്വം പാലിക്കുവാനും അപേക്ഷിക്കുന്നു.", "അമ്മർ ഇബ്നു യാസിർ (റ) (ഉദ്ഘാടന ഭാഗം) യുടെ പ്രാർത്ഥന.", "പ്രവാചകൻ സൽഹഅല്ലാഹു വസ്ലം പ്രാർത്ഥനയിൽ ഈ ദുആ ചെയ്തു."),
        "dua_ism_azam_mannan" to DuaText("ഇസ്മേ-ഇ-അസംഃ അൽ-മന്നാൻ", "അല്ലാഹുവേ, ഞാൻ നിന്നോടു യാചിക്കുന്നു. എല്ലാ സ്തുതിയും നിന്നുതന്നെയാണ്. നീയല്ലാതെ ഒരു ദൈവവുമില്ല. അനുഗ്രഹങ്ങൾ നൽകുന്നവനും, ആകാശങ്ങളുടെയും ഭൂമിയുടെയും സ്രഷ്ടാവുമായവൻ. ഓ പ്രതാപിയും ബഹുമാനവുമുള്ളവനേ, നിത്യജീവനായ രക്ഷിതാവേ!", "അല്ലാഹുവിൻറെ മഹത്തായ നാമം ഉപയോഗിച്ചാണ് ഈ മനുഷ്യൻ ദുആ നിർമ്മിച്ചതെന്ന് പ്രവാചകൻ പറഞ്ഞു.", "ഈ പേരിൽ നിർമ്മിച്ച ഒരു ദുആയ്ക്ക് ഉത്തരം നൽകുന്നു."),
        "dua_ism_azam_ahad_samad" to DuaText("ഇസ്മേ-ഇ-അസംഃ അൽ-അഹദ് അസ്-സമദ്", "അല്ലാഹുവേ, ഞാൻ നിന്നോടു യാചിക്കുന്നു, നീ അല്ലാഹുവാണെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു; നീയല്ലാതെ ഒരു ദൈവവുമില്ല, അവൻ ഏകനും സ്വയംപര്യാപ്തനുമാണ്, അവൻ ജനിക്കുകയോ ജനിക്കുകയോ ചെയ്യുന്നില്ല, അവനുമായി താരതമ്യപ്പെടുത്താവുന്ന ആരും ഇല്ല.", "നബി (സ) പറഞ്ഞുഃ ഈ മനുഷ്യൻ അല്ലാഹുവോട് അദ്ദേഹത്തിൻറെ ഏറ്റവും വലിയ നാമം ചോദിച്ചുവെന്ന്.", "അത് ചോദിക്കുമ്പോൾ അവൻ നൽകുന്നു; അത് വിളിക്കുമ്പോൾ അവൻ ഉത്തരം നൽകുന്നു."),
        "dua_thabbitni_hadiyan" to DuaText("എന്നെ ദൃഢവും മാർഗദർശിയും മാർഗ്ഗനിർദ്ദേശകനും ആക്കുക.", "അല്ലാഹുവേ, എന്നെ ഉറപ്പിച്ചുനിർത്തണമേ. എന്നെ നേർവഴിയിലാക്കുകയും നേർവഴിയിലാക്കുകയും ചെയ്യണമേ.", "നബി (സ) ഈ ദുആ ചെയ്തത് ജറീറിനു വേണ്ടിയാണ് (നിങ്ങൾക്ക്'തബ്ബിത്നി'എന്ന് പറയുക).", "ജാരിർ (ആർ. എ.) എന്നതിന്റെ യഥാർത്ഥ ദുആ'ഥാബിറ്റ്-ഹു'എന്ന വാക്കുകൾ ഉപയോഗിക്കുന്നു."),
        "dua_rabbighfir_tub_alayya" to DuaText("എന്നോട് ക്ഷമിക്കുകയും എൻ്റെ പശ്ചാത്താപം സ്വീകരിക്കുകയും ചെയ്യുക.", "എൻറെ രക്ഷിതാവേ, എന്നോട് നീ പൊറുത്തുതരികയും എൻറെ പശ്ചാത്താപം സ്വീകരിക്കുകയും ചെയ്യേണമേ. തീർച്ചയായും നീ പശ്ചാത്താപത്തിൻറെ ഉടമയും കരുണാനിധിയുമാകുന്നു.", "ഒരു ഇരിപ്പിടത്തിൽ നൂറ് തവണ-പ്രവാചകൻറെ ആചാരം.", "ഒരു ഇരിപ്പിൽ നൂറ് തവണ പ്രവാചകൻ പറഞ്ഞതായി കൂട്ടാളികൾ എണ്ണിയിട്ടുണ്ട്."),
        "dua_rafiq_ala" to DuaText("മരിച്ചുപോയ വ്യക്തിയുടെ ദുആ", "അല്ലാഹുവേ, എന്നോട് ക്ഷമിക്കണമേ, എന്നോട് കരുണ കാണിക്കണമേ, അത്യുന്നതനായ കൂട്ടാളിയുമായി എന്നോടൊപ്പം ചേരണമേ.", "പ്രവാചകൻറെ അവസാനത്തെ ദുആ-രോഗിയായ വ്യക്തിക്ക് സ്വയം പറയാനുള്ളതാണ്.", "നബി (സ) തൻ്റെ മരണസമയത്താണ് ഈ ദുആ ചെയ്തത്."),
        "dua_la_bas_tahur" to DuaText("രോഗിയെ ആശ്വസിപ്പിക്കുകഃ ശുദ്ധീകരണം", "ഒരു ദോഷവുമില്ല; അല്ലാഹു ഉദ്ദേശിക്കുന്നുവെങ്കിൽ അത് (പാപങ്ങളിൽ നിന്ന്) ഒരു ശുദ്ധീകരണമാണ്.", "സന്ദർശിക്കുമ്പോൾ രോഗികളെ ആശ്വസിപ്പിക്കുക.", "രോഗികളെ സന്ദർശിക്കുമ്പോഴാണ് പ്രവാചകൻ ഇത് പറഞ്ഞത്."),
        "dua_talqeen" to DuaText("മരണത്തിനായുള്ള തൽഖീൻ", "അല്ലാഹുവല്ലാതെ ആരാധിക്കപ്പെടാൻ ആർക്കും അവകാശമില്ല.", "മരിക്കുന്ന ഒരാളുടെ അടുത്ത് കലിമാ ചൊല്ലുക (അത് പറയാൻ അവരെ നിർബന്ധിക്കരുത്).", "'ലാ ഇലാഹ ഇല്ലല്ലാഹ്'എന്ന അവസാന വാക്കുകൾ ആരെങ്കിലും പറുദീസയിൽ പ്രവേശിക്കും (അബു ദാവൂദ് 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("മരണത്തിനായി ആഗ്രഹിക്കുന്നതിനുപകരം", "അല്ലാഹുവേ, എനിക്ക് ജീവിതം നന്നായിരിക്കുന്നിടത്തോളം കാലം എന്നെ ജീവിച്ചിരിക്കേണമേ, മരണം എനിക്ക് നല്ലതായിരിക്കുമ്പോൾ എന്നെ കൊണ്ടുപോകണമേ.", "കഷ്ടപ്പാടുകളിലുള്ള മരണം ആഗ്രഹിക്കുന്നതിനുപകരം.", "നബി (സ) മരണം ആഗ്രഹിക്കുന്നത് വിലക്കുകയും പകരം ഇത് പഠിപ്പിക്കുകയും ചെയ്തു."),
        "dua_for_one_i_cursed" to DuaText("ഞാൻ വാക്കുകളാൽ വേദനിപ്പിക്കുന്ന ഒരാൾക്ക്", "അല്ലാഹുവേ, ഞാൻ അപമാനിക്കുന്ന ഏതൊരു വിശ്വാസിയും ഉയിർത്തെഴുന്നേൽപിൻറെ നാളിൽ അവനെ നിൻറെ അടുത്തേക്ക് എത്തിക്കാനുള്ള ഒരു മാർഗ്ഗമാക്കി മാറ്റുക.", "നിങ്ങൾ ദേഷ്യത്തിൽ മോശമായി സംസാരിച്ച ഒരാൾക്ക് വേണ്ടി.", "നബി (സ) യുടെ ഒരു ദുആ."),
        "dua_praising_someone" to DuaText("ആരെയെങ്കിലും സ്തുതിക്കുമ്പോൾ", "ഞാൻ അങ്ങനെയാണ് കണക്കാക്കുന്നത്, അല്ലാഹു അവൻറെ റിക്കണറാണ്, അല്ലാഹുവിൻറെ മുമ്പിൽ ആരുടെയും വിശുദ്ധി ഞാൻ ഉറപ്പിക്കുകയില്ല.", "അതിശയോക്തിക്കു പകരം ആരെയെങ്കിലും സ്തുതിക്കുമ്പോൾ.", "പ്രവാചകൻ സൽഹഅല്ലാഹു വസ്ലം ഈ സ്തുതിയുടെ മര്യാദ പഠിപ്പിച്ചു."),
        "dua_being_praised" to DuaText("നിങ്ങൾ സ്തുതിക്കപ്പെടുമ്പോൾ", "അല്ലാഹുവേ, അവർ പറയുന്നതൊക്കെ നീ എന്നോട് പറയരുത്. അവർ അറിയാത്തതൊക്കെ എന്നോട് ക്ഷമിക്കണമേ.", "സ്വയം പ്രശംസിക്കുന്നത് കേൾക്കുമ്പോൾ-ഒരു കമ്പാനിയൻ (ആർ. എ) എന്ന അഭ്യാസം.", "പ്രശംസിക്കുമ്പോൾ അഹങ്കാരം ഒഴിവാക്കാനുള്ള ഒരു മാർഗ്ഗം."),
        "dua_non_muslim_sneezes" to DuaText("ഒരു അമുസ്ലിം തുമ്മുമ്പോൾ", "അല്ലാഹു നിങ്ങളെ നയിക്കുകയും നിങ്ങളുടെ കാര്യങ്ങൾ ശരിയായി ക്രമീകരിക്കുകയും ചെയ്യട്ടെ.", "ഒരു അമുസ്ലിം തുമ്മുകയും'അൽഹംദുലില്ലാഹ്'എന്ന് പറയുകയും ചെയ്യുമ്പോൾ.", "പ്രവാചകൻ'യർഹമുകല്ലാഹ്'എന്ന് പറയുമെന്ന് പ്രതീക്ഷിച്ചുകൊണ്ട് ജൂതന്മാർ പ്രവാചകൻറെ അടുത്ത് തുമ്മുകയും അദ്ദേഹം ഇത് പറയുകയും ചെയ്യും."),
        "dua_reply_ahl_kitab_salam" to DuaText("പുസ്തകത്തിലെ ആളുകളുടെ സലാമിന് മറുപടി", "ഒപ്പം നിങ്ങളുടെയും.", "വേദക്കാർ നമസ്കാരത്തോടെ അഭിവാദ്യം ചെയ്യുമ്പോൾ.", "നബി (സ) യുടെ നിർദ്ദേശം."),
        "dua_fasting_invited" to DuaText("ഉപവാസം ചെയ്യുമ്പോൾ ക്ഷണിക്കപ്പെടുമ്പോൾ", "ഞാൻ ഉപവാസം അനുഷ്ഠിക്കുന്നു.", "ഉപവാസം ചെയ്യുമ്പോൾ ക്ഷണിക്കപ്പെടുമ്പോഴോ അല്ലെങ്കിൽ ആരെങ്കിലും നിങ്ങളുമായി തർക്കിക്കുമ്പോഴോ.", "ഉപവാസം ചെയ്യുന്ന വ്യക്തി ഒരു ക്ഷണം സ്വീകരിക്കുകയാണെങ്കിൽ, അവൻ ആതിഥേയർക്കായി പ്രാർത്ഥിക്കണം."),
        "dua_for_who_gave_drink" to DuaText("എന്നെ പോഷിപ്പിച്ചവർക്ക്", "അല്ലാഹുവേ, എനിക്ക് ഭക്ഷണം നൽകിയവന് ഭക്ഷണം നൽകുകയും എനിക്ക് പാനീയം നൽകിയവന് കുടിക്കുകയും ചെയ്യേണമേ.", "നിങ്ങൾക്ക് ഭക്ഷണമോ പാനീയമോ നൽകുന്നവർക്ക് വേണ്ടി.", "നബി (സ) അൽ-മിഖ്ദാദിന് വേണ്ടി ഈ ദുആ ഉണ്ടാക്കി."),
        "dua_eid_greeting" to DuaText("ഈദ് ആശംസകൾ", "ഞങ്ങളിൽ നിന്നും നിങ്ങളിൽ നിന്നും അല്ലാഹു (സൽകർമ്മങ്ങൾ) സ്വീകരിക്കട്ടെ.", "ഈദ് ദിനത്തിൽ പരസ്പരം-കുലീനരായ കൂട്ടാളികൾ (ആർ. എ.).", "ഈദിൽ കണ്ടുമുട്ടിയപ്പോഴാണ് കൂട്ടുകാർ ഇത് പറഞ്ഞത്."),
        "dua_wedding_night" to DuaText("നിക്കയ്ക്ക് ശേഷമുള്ള വധുവിന്", "അല്ലാഹുവേ, നീ അവളെ സൃഷ്ടിച്ച പ്രകൃതിയുടെ നന്മയും നന്മയും ഞാൻ നിന്നോടു ചോദിക്കുന്നു. നീ അവളെ സൃഷ്ടിച്ച പ്രകൃതിയുടെ തിന്മയിൽ നിന്നും തിന്മയിൽ നിന്നും ഞാൻ നിന്നിൽ അഭയം തേടുന്നു.", "വിവാഹശേഷം ഭാര്യയുടെ നെറ്റിയിൽ കൈ വയ്ക്കുക.", "പ്രവാചകൻറെ സൽഹഅല്ലാഹു വസ്ലം പഠിപ്പിക്കൽ-വിവാഹത്തിൽ അനുഗ്രഹം."),
        "dua_istisqa_ibadak" to DuaText("നിങ്ങളുടെ ദാസന്മാർക്കും മൃഗങ്ങൾക്കും വെള്ളം നൽകുക", "അല്ലാഹുവേ, നിൻറെ ദാസന്മാർക്കും മൃഗങ്ങൾക്കും വെള്ളം നൽകുകയും, നിൻറെ കാരുണ്യം പരത്തുകയും, നിൻറെ മൃതഭൂമിയെ ജീവിക്കുകയും ചെയ്യേണമേ.", "മഴ ആവശ്യപ്പെടുന്നു (ഇസ്തിസ്ഖ).", "പ്രവാചകൻ സൽഹുല്ലാഹ്ലാഹു അലൈഹി വസല്ലം മഴയ്ക്കായി ഈ ദുആ ഉണ്ടാക്കി."),
        "dua_seeing_clouds" to DuaText("ഇരുണ്ട മേഘങ്ങൾ കാണുന്നു", "അല്ലാഹുവേ, അതിൻറെ തിന്മകളിൽനിന്ന് ഞാൻ അങ്ങയിൽ അഭയം തേടുന്നു.", "ആകാശത്ത് ഇരുണ്ട മേഘങ്ങൾ കാണുമ്പോൾ; മഴ പെയ്താൽ'അല്ലാഹുമ്മ സയ്യിബൻ നഫിയാ'എന്ന് പറയുക.", "മേഘങ്ങൾ കാണുമ്പോൾ, പ്രവാചകൻ സൽഹഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹുഅല്ലാഹു"),
        "dua_jamarat" to DuaText("ജമറാത്തിനെ കല്ലെറിയുന്നു", "അല്ലാഹു ഏറ്റവും വലിയവനാണ്.", "ഓരോ കല്ലും എറിഞ്ഞുകൊണ്ട്.", "നബി (സ) ഓരോ കല്ലും ഉപയോഗിച്ച് തക്ബീർ പറയുകയും ഒന്നും രണ്ടും ജംറകൾക്ക് ശേഷം ഖിബ്ലയെ അഭിമുഖീകരിക്കുകയും ഒരു നീണ്ട ദുആ നടത്തുകയും ചെയ്തു."),
        "dua_rabbi_ainni" to DuaText("എൻറെ കർത്താവേ, എന്നെ സഹായിക്കണമേ, എനിക്കെതിരെയല്ല.", "എൻറെ രക്ഷിതാവേ, എന്നെ സഹായിക്കേണമേ, എനിക്കെതിരെ മറ്റുള്ളവരെ സഹായിക്കാതിരിക്കേണമേ, എനിക്ക് വിജയം നൽകുകയും, മറ്റുള്ളവർക്ക് എന്നെ വിജയിക്കാതിരിക്കുകയും ചെയ്യേണമേ, എനിക്കുവേണ്ടി ആസൂത്രണം ചെയ്യുകയും, എനിക്കെതിരെ ആസൂത്രണം ചെയ്യാതിരിക്കുകയും, എന്നെ നയിക്കുകയും, എനിക്ക് മാർഗദർശനം എളുപ്പമാക്കുകയും, എന്നോട് അനീതി കാണിക്കുന്നവർക്കെതിരെ എന്നെ സഹായിക്കുകയും ചെയ്യണമേ.", "പ്രവാചകൻറെ സമഗ്രമായ ഒരു ദുആ (ഉദ്ഘാടന ഭാഗം).", "മതത്തിലും ഈ ലോകത്തും എല്ലാ സഹായവും ശേഖരിക്കുന്ന ഒരു ദുആ."),
        "dua_ati_nafsi_taqwaha" to DuaText("എൻ്റെ ആത്മാവിന് അതിൻ്റെ തഖ് വാ നൽകുക.", "അല്ലാഹുവേ, എൻറെ ആത്മാവിന് അതിൻറെ ധർമ്മനിഷ്ഠ നൽകുകയും അതിനെ ശുദ്ധീകരിക്കുകയും ചെയ്യേണമേ. നീയാണ് അതിനെ ശുദ്ധീകരിക്കാൻ ഏറ്റവും നല്ലവൻ. നീയാണ് അതിൻറെ രക്ഷാധികാരിയും യജമാനനും.", "സ്വയം പരിഷ്ക്കരിക്കുന്നതിനും ശുദ്ധീകരിക്കുന്നതിനും.", "നബി (സ) ഈ ദുആ ഉണ്ടാക്കാറുണ്ടായിരുന്നു."),
        "dua_iqsim_lana_khashyatik" to DuaText("അങ്ങയെക്കുറിച്ചുള്ള അത്തരം ഭയം ഞങ്ങൾക്ക് നൽകുക.", "അല്ലാഹുവേ, ഞങ്ങൾക്കിടയിൽ വരുന്നതിനും നിന്നെ അനുസരിക്കാത്തതിനും നീ ഞങ്ങളെ നിൻറെ സ്വർഗത്തിലേക്ക് കൊണ്ടുവരാൻ മതിയായ അനുസരണവും ഈ ലോകത്തിലെ ദുരന്തങ്ങൾ ഞങ്ങൾക്ക് എളുപ്പമാക്കുന്നതിന് മതിയായ ഉറപ്പും നൽകുക. നീ ഞങ്ങളെ ജീവിച്ചിരിക്കുന്നിടത്തോളം കാലം ഞങ്ങൾക്ക് ഞങ്ങളുടെ കേൾവിയും കാഴ്ചയും ശക്തിയും ആസ്വദിക്കാം. അവ ഞങ്ങളെ നിലനിർത്തുകയും ചെയ്യുക. ഞങ്ങളോട് അനീതി കാണിക്കുന്നവർക്ക് നേരെ പ്രതികാരം ചെയ്യുക. ഞങ്ങളുടെ ശത്രുക്കളോട് ഞങ്ങളെ സഹായിക്കുക. ഞങ്ങളുടെ മതം ഞങ്ങളുടെ ദുരന്തമായി മാറരുത്. ഈ ലോകത്തെ ഞങ്ങളുടെ ഏറ്റവും വലിയ ആശങ്കയോ ഞങ്ങളുടെ അറിവിൻറെ പരിധിയോ ആക്കരുത്. ഞങ്ങൾക്ക് ദയ കാണിക്കാത്തവരെ ഞങ്ങളുടെ മേൽ നിർത്തരുത്.", "ഒരു കൂട്ടത്തിൽ നിന്ന് എഴുന്നേൽക്കുമ്പോൾ-നബി (സ) ഈ ദുആ ചെയ്യാതെ അപൂർവ്വമായി മാത്രമേ എഴുന്നേറ്റുള്ളൂ.", "മതത്തിൻ്റെയും ഈ ലോകത്തിൻ്റെയും പരലോകത്തിൻ്റെയും നന്മയ്ക്കായി സമഗ്രമായ ഒരു ദുആ."),
        "dua_infani_bima_allamtani" to DuaText("നിങ്ങൾ എന്നെ പഠിപ്പിച്ച കാര്യങ്ങൾ കൊണ്ട് എനിക്ക് പ്രയോജനം ചെയ്യുക.", "അല്ലാഹുവേ, നീ എന്നെ പഠിപ്പിച്ചതുകൊണ്ട് എനിക്ക് പ്രയോജനം ചെയ്യുക, എനിക്ക് പ്രയോജനം ചെയ്യുന്നത് എന്നെ പഠിപ്പിക്കുക, എന്നെ അറിവ് വർദ്ധിപ്പിക്കുക.", "അറിവ് തേടുമ്പോഴോ പഠിക്കുന്നതിന് മുമ്പോ.", "പ്രയോജനകരമായ അറിവിനും അതിൽ പ്രവർത്തിക്കുന്നതിനും വേണ്ടിയുള്ള ഒരു ദുആ."),
    )
}
